class Solution {
public:
    vector<vector<int>> spiralMatrix(int m, int n, ListNode* head) {
        vector<vector<int>> ans(m, vector<int>(n, -1));
        int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int d = 0;
        int i = 0, j = 0;
        while (head != nullptr) {
            ans[i][j] = head->val;
            int ni = i + dirs[d][0];
            int nj = j + dirs[d][1];
            if (ni < 0 || ni >= m || nj < 0 || nj >= n || ans[ni][nj] != -1) {
                d = (d + 1) % 4;
                ni = i + dirs[d][0];
                nj = j + dirs[d][1];
            }
            i = ni;
            j = nj;
            head = head->next;
        }
        return ans;
    }
};
